// src/lib/mcp/supabase.ts
import { createClient } from "npm:@supabase/supabase-js@^2.112.2";
function runtimeEnv(name) {
  const runtime = globalThis;
  return runtime.Deno?.env?.get?.(name) ?? runtime.process?.env?.[name];
}
function configuredEnv(names) {
  for (const name of names) {
    const value = runtimeEnv(name)?.trim();
    if (value) return value;
  }
  return void 0;
}
function supabaseProjectUrl() {
  const url = configuredEnv(["SUPABASE_URL", "VITE_SUPABASE_URL"]);
  if (!url) throw new Error("SUPABASE_URL (or VITE_SUPABASE_URL) is required");
  return url;
}
function supabasePublishableKey() {
  const direct = configuredEnv([
    "SUPABASE_PUBLISHABLE_KEY",
    "VITE_SUPABASE_PUBLISHABLE_KEY"
  ]);
  if (direct) return direct;
  const keyset = runtimeEnv("SUPABASE_PUBLISHABLE_KEYS");
  if (keyset) {
    try {
      const parsed = JSON.parse(keyset);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        const keys = parsed;
        const key = [keys.default, ...Object.values(keys)].find((v) => typeof v === "string" && v.trim().startsWith("sb_publishable_"))?.trim();
        if (key) return key;
      }
    } catch {
    }
  }
  const legacy = configuredEnv(["SUPABASE_ANON_KEY", "VITE_SUPABASE_ANON_KEY"]);
  if (legacy) return legacy;
  throw new Error("SUPABASE_PUBLISHABLE_KEY, SUPABASE_PUBLISHABLE_KEYS, or SUPABASE_ANON_KEY is required");
}
function supabaseForUser(ctx) {
  const token = ctx.getToken();
  if (!token) throw new Error("supabaseForUser requires a verified OAuth token");
  return createClient(supabaseProjectUrl(), supabasePublishableKey(), {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}

// src/lib/mcp/tools/get-city-news.ts
var SITE = "https://localnews.meenai.in";
var slugify = (v) => v.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
var get_city_news_default = defineTool2({
  name: "get_city_news",
  title: "Get city news",
  description: "Get the latest published news stories for an Indian city covered by Local News, newest first. Returns bilingual headlines and summaries plus links.",
  inputSchema: {
    city: z2.string().describe("City name, e.g. 'Alwar' or 'Jaipur'."),
    category: z2.string().optional().describe("Optional category filter, e.g. Politics, Crime, Sports."),
    limit: z2.number().int().optional().describe("Maximum stories to return (default 10, max 50).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ city, category, limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    let q = supabase.from("news_articles").select("title_en,title_hi,summary_en,summary_hi,category,source_name,source_url,published_at,slug,city").ilike("city", city.trim()).order("published_at", { ascending: false }).limit(Math.min(Math.max(limit ?? 10, 1), 50));
    if (category?.trim()) q = q.eq("category", category.trim());
    const { data, error } = await q;
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    const stories = (data ?? []).map((a) => ({
      title: a.title_en,
      titleHi: a.title_hi,
      summary: a.summary_en,
      summaryHi: a.summary_hi,
      category: a.category,
      source: a.source_name,
      sourceUrl: a.source_url,
      publishedAt: a.published_at,
      pageUrl: a.slug ? `${SITE}/news/${slugify(a.city)}/${a.slug}` : `${SITE}/news/${slugify(a.city)}`
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(stories, null, 2) }],
      structuredContent: { city, count: stories.length, stories }
    };
  }
});

// src/lib/mcp/tools/search-news.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z3 } from "npm:zod@^3.25.76";
var SITE2 = "https://localnews.meenai.in";
var slugify2 = (v) => v.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
var search_news_default = defineTool3({
  name: "search_news",
  title: "Search news",
  description: "Search published Local News stories across all cities by keyword in the English or Hindi headline, newest first.",
  inputSchema: {
    query: z3.string().describe("Keyword or phrase to search for in headlines."),
    limit: z3.number().int().optional().describe("Maximum stories to return (default 10, max 50).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ query, limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    const term = query.trim();
    if (!term) return { content: [{ type: "text", text: "query must not be empty" }], isError: true };
    const supabase = supabaseForUser(ctx);
    const pattern = `%${term.replace(/[%,]/g, " ")}%`;
    const { data, error } = await supabase.from("news_articles").select("title_en,title_hi,summary_en,summary_hi,category,city,source_name,source_url,published_at,slug").or(`title_en.ilike.${pattern},title_hi.ilike.${pattern}`).order("published_at", { ascending: false }).limit(Math.min(Math.max(limit ?? 10, 1), 50));
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    const stories = (data ?? []).map((a) => ({
      title: a.title_en,
      titleHi: a.title_hi,
      summary: a.summary_en,
      summaryHi: a.summary_hi,
      city: a.city,
      category: a.category,
      source: a.source_name,
      sourceUrl: a.source_url,
      publishedAt: a.published_at,
      pageUrl: a.slug ? `${SITE2}/news/${slugify2(a.city)}/${a.slug}` : `${SITE2}/news/${slugify2(a.city)}`
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(stories, null, 2) }],
      structuredContent: { query: term, count: stories.length, stories }
    };
  }
});

